import { useState } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyValues: SignupValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const summaryRows: { label: string; key: keyof SignupValues }[] = [
  { label: 'Имя', key: 'name' },
  { label: 'Электронная почта', key: 'email' },
  { label: 'Телефон', key: 'phone' },
  { label: 'Город', key: 'city' },
  { label: 'Улица и дом', key: 'street' },
  { label: 'Индекс', key: 'zip' },
];

export default function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState(emptyValues);

  const isLastStep = step === steps.length - 1;

  const setField =
    (key: keyof SignupValues) => (event: React.ChangeEvent<HTMLInputElement>) => {
      const next = event.target.value;
      setValues((current) => ({ ...current, [key]: next }));
    };

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLastStep) {
      onSubmit(values);
      return;
    }
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: 24 }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: 16 }}>
          <JxInputField
            label="Имя"
            required
            autoComplete="name"
            value={values.name}
            onChange={setField('name')}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            autoComplete="email"
            value={values.email}
            onChange={setField('email')}
            helperText="На неё придёт письмо для подтверждения"
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            autoComplete="tel"
            value={values.phone}
            onChange={setField('phone')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: 16 }}>
          <JxInputField
            label="Город"
            required
            autoComplete="address-level2"
            value={values.city}
            onChange={setField('city')}
          />
          <JxInputField
            label="Улица и дом"
            required
            autoComplete="street-address"
            value={values.street}
            onChange={setField('street')}
          />
          <JxInputField
            label="Индекс"
            inputMode="numeric"
            autoComplete="postal-code"
            value={values.zip}
            onChange={setField('zip')}
          />
        </div>
      )}

      {step === 2 && (
        <dl
          style={{
            display: 'grid',
            gridTemplateColumns: 'minmax(0, 1fr) minmax(0, 1fr)',
            gap: 12,
            margin: 0,
            padding: 20,
            background: 'var(--jx-surface-2)',
            border: '1px solid var(--jx-border)',
            borderRadius: 'var(--jx-r)',
            fontFamily: 'var(--jx-font-sans)',
          }}
        >
          {summaryRows.map((row) => (
            <div key={row.key} style={{ display: 'contents' }}>
              <dt style={{ color: 'var(--jx-text-2)' }}>{row.label}</dt>
              <dd style={{ margin: 0, color: 'var(--jx-text)' }}>
                {values[row.key] || '—'}
              </dd>
            </div>
          ))}
        </dl>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8 }}>
        <JxButton
          variant="ghost"
          type="button"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

